-- Seed catalog for Superhuman Coach.
-- IMPORTANT: affiliate_urls are intentionally empty. Replace them only with affiliate URLs
-- from programs you are actually approved for. destination_urls are ordinary merchant/search
-- destinations and do not generate commissions.
on conflict (slug) do update set
  name=excluded.name, category=excluded.category, merchant_default=excluded.merchant_default,
  image_url=excluded.image_url, price_label=excluded.price_label, reason_key=excluded.reason_key,
  tags=excluded.tags, goals=excluded.goals, levels=excluded.levels, space_requirement=excluded.space_requirement,
  regions=excluded.regions, destination_urls=excluded.destination_urls, priority=excluded.priority, active=excluded.active;
